const limitOf=(value)=>Math.max(1,Math.min(100,Number.isInteger(value)?value:25));
const result=(value)=>({content:[{type:"text",text:JSON.stringify(value,null,2)}],structuredContent:value,isError:false});
const failure=(message)=>({content:[{type:"text",text:message}],isError:true});
function callApiTool(name,args,data){const route=apiToolRoutes[name];if(!route)return null;const url=new URL(`http://localhost${route}`);if(name==="review_isolated_snapshot_corpora")url.searchParams.set("view","isolated");for(const [key,value] of Object.entries(args??{})){const parameter=key==="query"?"q":key;if(Array.isArray(value))for(const item of value)url.searchParams.append(parameter==="levels"?"level":parameter,String(item));else if(value!=null&&value!=="")url.searchParams.set(parameter,String(value))}const response=routeResearchApi(route,url,data);return response.status===200?result(response.body):failure(response.body.error??`API route failed: ${route}`)}
function callTool(name,args,data){const site=data.sites.find((row)=>row.site_id===args.site_id);if(name!=="get_content_brief"&&!site)return failure(`unknown site_id: ${args.site_id}`);const limit=limitOf(args.limit),query=String(args.query??"").normalize("NFKC").trim().toLocaleLowerCase("ja-JP");if(name==="search_keywords")return result(data.keyword_inventory.filter((row)=>row.site_id===args.site_id&&row.raw_keyword.toLocaleLowerCase("ja-JP").includes(query)).slice(0,limit));if(name==="search_demands"){const groupIds=new Set(data.groups.filter((row)=>row.site_id===args.site_id).map((row)=>row.id));return result(data.serp_demands.filter((row)=>row.group_ids.some((id)=>groupIds.has(id))&&(args.demand_type==null||args.demand_type==="all"||row.demand_type===args.demand_type)&&(!query||`${row.representative_value} ${row.source_keywords.join(" ")}`.toLocaleLowerCase("ja-JP").includes(query))).slice(0,limit))}if(name==="list_question_candidates")return result(site.ai_question_candidates.filter((row)=>args.candidate_kind==null||args.candidate_kind==="all"||row.candidate_kind===args.candidate_kind).slice(0,limit));if(name==="get_content_brief"){const group=data.groups.find((row)=>row.id===args.group_id),structure=data.content_structure_candidates.find((row)=>row.group_id===args.group_id);return group&&structure?result({group,structure,generation_candidates:data.content_generation_candidates.filter((row)=>row.group_id===args.group_id)}):failure(`unknown group_id: ${args.group_id}`)}if(name==="get_acquisition_status")return result({site_id:site.site_id,keyword_count:data.keyword_inventory.filter((row)=>row.site_id===site.site_id).length,serp_unacquired_count:data.keyword_inventory.filter((row)=>row.site_id===site.site_id&&row.processing_state==="SERP未取得").length,provider_cost_ledger:site.provider_cost_ledger,credentials_exposed:false});return failure(`unknown tool: ${name}`)}
export function handleMcpMessage(message,data){const id=message?.id;if(message?.jsonrpc!=="2.0"||typeof message.method!=="string")return{jsonrpc:"2.0",id:id??null,error:{code:-32600,message:"Invalid Request"}};if(message.method==="initialize"){const requested=message.params?.protocolVersion;return{jsonrpc:"2.0",id,result:{protocolVersion:protocolVersions.has(requested)?requested:defaultProtocol,capabilities:{tools:{listChanged:false}},serverInfo:{name:"helix-seo-research",version:"0.9.0"},instructions:"Read-only, site-scoped retained evidence. External acquisition is never triggered by these tools."}}}if(message.method==="ping")return{jsonrpc:"2.0",id,result:{}};if(message.method==="tools/list")return{jsonrpc:"2.0",id,result:{tools}};if(message.method==="tools/call"){const name=message.params?.name,args=message.params?.arguments??{},toolResult=callApiTool(name,args,data)??callTool(name,args,data);return{jsonrpc:"2.0",id,result:toolResult}}if(message.method.startsWith("notifications/"))return null;return{jsonrpc:"2.0",id,error:{code:-32601,message:"Method not found"}}}
export function isAllowedMcpOrigin(origin){if(!origin)return true;try{return["localhost","127.0.0.1","::1"].includes(new URL(origin).hostname)}catch{return false}}
